const localNuc=['127.0.0.1','localhost','::1'].includes(location.hostname)&&!window.DartsAndroid;
const button=document.createElement('button');button.id='online-game';button.type='button';button.textContent='Online dartbaan';document.getElementById('top-actions').append(button);
const dialog=document.createElement('dialog');dialog.id='online-dialog';dialog.className='online-dialog';dialog.innerHTML=`<h2>Online dartbaan - 4 op een rij</h2><p>Maak een besloten dartbaan voor 2 tot 4 spelers of sluit aan met een uitnodiging.</p><fieldset><legend>Dartbaan maken</legend><label>Jouw naam<input id="online-host-name" maxlength="24" autocomplete="name"></label><label>Aantal spelers<select id="online-capacity"><option>2</option><option>3</option><option>4</option></select></label><button id="online-host" class="primary wide">Dartbaan maken</button></fieldset><fieldset><legend>Deelnemen aan dartbaan</legend><label>Jouw naam<input id="online-guest-name" maxlength="24" autocomplete="name"></label><label>Uitnodigingslink<input id="online-invite-input" autocomplete="off" placeholder="https://voorbeeld.trycloudflare.com/?dartbaan=ABC123"></label><button id="online-join" class="primary wide">Deelnemen aan dartbaan</button></fieldset><section id="online-active" hidden><h3>Actieve dartbaan</h3><p id="online-invite" class="online-invite" tabindex="0"></p><button id="online-copy" class="wide">Uitnodiging kopiëren</button></section><p id="online-status" class="online-dialog-status" role="status"></p><div class="online-actions"><button id="online-leave">Dartbaan verlaten</button><button id="online-close">Sluiten</button></div>`;document.body.append(dialog);
const indicator=document.createElement('div');indicator.id='online-indicator';indicator.hidden=true;document.body.append(indicator);
const $=id=>document.getElementById(id),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));let session=null,syncing=false;
async function json(url,options={}){const response=await fetch(url,{cache:'no-store',...options});let data={};try{data=await response.json();}catch{}if(!response.ok){const error=Error(data.error||`Verbinding mislukt (${response.status}).`);error.status=response.status;error.data=data;throw error;}return data;}
async function localState(){return json('/api/state');}
async function saveLocal(match){const current=await localState();return json('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:current.revision,match})});}
async function saveSession(value){session=value;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});paint();}
function invite(){return session?.active?`${session.base}/?dartbaan=${session.code}`:'';}
function paint(state=null){
 const active=!!session?.active;$('online-active').hidden=!active;$('online-leave').hidden=!active;$('online-invite').textContent=active?invite():'';indicator.hidden=!active;document.body.classList.toggle('online-session',active);
 if(!active){document.body.classList.remove('online-waiting');return;}
 const waiting=!session.ready||(state?.state?.active!==undefined&&state.state.active!==session.role);document.body.classList.toggle('online-waiting',waiting);
 const count=state?.state?.players?.filter(player=>!player.name.startsWith('Wachten op speler')).length;
 indicator.textContent=`Online dartbaan ${session.code} - speler ${session.role+1}${count?` - ${count}/${state.state.players.length} aanwezig`:''}${!session.ready?' - wacht op spelers':state?.state?.phase==='playing'?(waiting?' - tegenstander aan de beurt':' - jij bent aan de beurt'):''}`;
}
function parseInvite(value){const url=new URL(value.trim());if(!/^[a-z0-9-]+\.trycloudflare\.com$/.test(url.hostname))throw Error('Gebruik de uitnodigingslink van 180 Hitters.');const code=(url.searchParams.get('dartbaan')||url.hash.replace(/^#/,'')).toUpperCase();if(!/^[A-Z2-9]{6}$/.test(code))throw Error('De dartbaancode ontbreekt in de uitnodiging.');return {base:url.origin,code};}
async function waitTunnel(){for(let attempt=0;attempt<90;attempt++){const status=await json('/api/online/tunnel');$('online-status').textContent=status.status==='starting'?'Beveiligde testverbinding maken...':status.error||'';if(status.status==='ready')return status.url;if(status.status==='error')throw Error(status.error);await sleep(700);}throw Error('De internettunnel startte niet op tijd.');}
button.onclick=async()=>{try{session=await json('/api/online/local');paint();}catch{}dialog.showModal();};$('online-close').onclick=()=>dialog.close();
$('online-host').onclick=async()=>{const name=$('online-host-name').value.trim(),capacity=Number($('online-capacity').value);if(!name)return $('online-status').textContent='Vul jouw naam in.';$('online-host').disabled=true;try{
 $('online-status').textContent='Tijdelijke beveiligde verbinding starten...';await json('/api/online/tunnel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'start'})});const base=await waitTunnel();
 const {newMatch}=await import('./engine.js'),names=[name,...Array.from({length:capacity-1},(_,index)=>`Wachten op speler ${index+2}`)],state=newMatch(names,0,'single',1,{game:'fourinarow'}),match={state,undo:[]};await saveLocal(match);
 const remote=await json(base+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,match})});await saveLocal(remote.match);await saveSession({active:true,ready:remote.joined>=remote.capacity,role:remote.role,code:remote.code,base,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent='Dartbaan gereed. Deel de uitnodiging.';
 }catch(error){$('online-status').textContent=error.message;}finally{$('online-host').disabled=false;}};
$('online-join').onclick=async()=>{const name=$('online-guest-name').value.trim();if(!name)return $('online-status').textContent='Vul jouw naam in.';$('online-join').disabled=true;try{const target=parseInvite($('online-invite-input').value),remote=await json(`${target.base}/rooms/${target.code}/join`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await saveLocal(remote.match);await saveSession({active:true,ready:remote.joined>=remote.capacity,role:remote.role,code:remote.code,base:target.base,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent='Verbonden met de dartbaan.';}catch(error){$('online-status').textContent=error.message;}finally{$('online-join').disabled=false;}};
$('online-copy').onclick=async()=>{try{await navigator.clipboard.writeText(invite());$('online-status').textContent='Uitnodiging gekopieerd.';}catch{$('online-invite').focus();const selection=getSelection();selection.removeAllRanges();const range=document.createRange();range.selectNodeContents($('online-invite'));selection.addRange(range);$('online-status').textContent='Selecteer en kopieer de uitnodiging.';}};
$('online-leave').onclick=async()=>{const wasHost=session?.role===0;try{await saveSession({active:false,ready:false,role:null,code:'',base:'',key:'',remoteRevision:0});if(wasHost)await json('/api/online/tunnel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'stop'})});$('online-status').textContent='Dartbaan verlaten.';}catch(error){$('online-status').textContent=error.message;}};
async function sync(){if(syncing)return;syncing=true;try{
 const configured=await json('/api/online/local');if(!configured.active){session=configured;paint();return;}session=configured;
 const [remote,local]=await Promise.all([json(`${session.base}/rooms/${session.code}?key=${encodeURIComponent(session.key)}`),localState()]);const localMatch=local.match,remoteMatch=remote.match;if(!localMatch?.state||!remoteMatch?.state)throw Error('Partijstand ontbreekt.');
 const ready=remote.joined>=remote.capacity;if(session.ready!==ready){session.ready=ready;await saveSession(session);}
 const localHistory=localMatch.state.history.length,remoteHistory=remoteMatch.state.history.length;
 if(localHistory===remoteHistory+1&&remoteMatch.state.active===session.role){const updated=await json(`${session.base}/rooms/${session.code}/state`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:session.key,revision:remote.revision,match:localMatch})});session.remoteRevision=updated.revision;await saveSession(session);paint(updated.match);return;}
 if(remote.revision!==session.remoteRevision||JSON.stringify(localMatch.state)!==JSON.stringify(remoteMatch.state)){await saveLocal(remoteMatch);session.remoteRevision=remote.revision;await saveSession(session);}
 paint(remoteMatch);
 }catch(error){if(session?.active){indicator.hidden=false;indicator.textContent='Online dartbaan - verbinding herstellen...';$('online-status').textContent=error.message;}}finally{syncing=false;}}
document.addEventListener('click',event=>{if(!session?.active)return;const blocked=document.body.classList.contains('online-waiting')&&event.target.closest('.four-board,.four-controls')||event.target.closest('#undo,#redo,#edit-match,#team-manager,#settings');if(blocked){event.preventDefault();event.stopImmediatePropagation();$('online-status').textContent='Verlaat eerst de online dartbaan om deze functie te gebruiken.';}},true);
async function restore(){try{session=await json('/api/online/local');paint();}catch{}if(localNuc)setInterval(sync,650);else setInterval(async()=>{try{session=await json('/api/online/local');const local=await localState();paint(local.match);}catch{}},1200);}restore();
